using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace LWS.InterstateHauler.Editor
{
    // All vendor calls stay here. Geometry and collision are generated by EasyRoads.
    internal sealed class EdenboroughEasyRoadsAdapter
    {
        private const string PrefabPath = "Assets/EasyRoads3D/Resources/ERRoadNetwork.prefab";
        private readonly Type baseType = RequireType("ERModularBase");
        private readonly Type roadType = RequireType("ERRoadType");
        private readonly Type markerType = RequireType("ERMarkerControlType");
        private readonly object network;
        private readonly Component modularBase;
        private readonly GameObject instance;
        private readonly Material material;

        internal EdenboroughEasyRoadsAdapter(Scene scene, Transform parent, Material roadMaterial)
        {
            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(PrefabPath);
            if (prefab == null || prefab.GetComponent(baseType) == null)
                throw new InvalidOperationException("EasyRoads ERRoadNetwork prefab / ERModularBase is unavailable.");
            material = roadMaterial;
            instance = (GameObject)PrefabUtility.InstantiatePrefab(prefab, scene);
            instance.name = "Edenborough EasyRoads Network";
            instance.transform.SetParent(parent, false);
            modularBase = instance.GetComponent(baseType);
            Call(modularBase, "RoadNetworkInit", Type.EmptyTypes);
            // An explicit component prevents ERRoadNetwork from finding another loaded scene's network.
            network = RequireType("ERRoadNetwork").GetConstructor(new[] { baseType })
                ?.Invoke(new object[] { modularBase })
                ?? throw new MissingMethodException("ERRoadNetwork(ERModularBase)");
        }

        internal Component CreateRoad(string name, Vector3[] markers, float width, bool oneWay, string osmClass)
        {
            object specification = Activator.CreateInstance(roadType);
            Set(specification, "roadTypeName", "Edenborough " + width.ToString("F2",
                System.Globalization.CultureInfo.InvariantCulture));
            Set(specification, "roadWidth", width);
            Set(specification, "hasMeshCollider", true);
            Set(specification, "roadMaterial", material);
            Array controls = Array.CreateInstance(markerType, markers.Length);
            object straight = Enum.Parse(markerType, "StraightXZ");
            for (int i = 0; i < controls.Length; i++) controls.SetValue(straight, i);
            object road = Call(network, "CreateRoad",
                new[] { typeof(string), roadType, typeof(Vector3[]), markerType.MakeArrayType() },
                name, specification, markers, controls);
            if (road == null) throw new InvalidOperationException("EasyRoads CreateRoad returned null: " + name);
            var modularRoad = road.GetType().GetField("roadScript")?.GetValue(road) as Component;
            if (modularRoad == null || modularRoad.GetType() != RequireType("ERModularRoad") ||
                modularRoad.GetType().GetField("baseScript")?.GetValue(modularRoad) as Component != modularBase)
                throw new InvalidOperationException("Created road does not belong to the isolated ERModularBase.");
            Set(modularRoad, "oneWayRoad", oneWay);
            Set(modularRoad, "osmRoadType", osmClass);
            Call(road, "SetMeshCollider", new[] { typeof(bool) }, true);
            Call(road, "SetTerrainDeformation", new[] { typeof(bool), typeof(bool) }, false, false);
            Call(road, "SnapToTerrain", new[] { typeof(bool), typeof(bool) }, false, false);
            Call(road, "SetResolution", new[] { typeof(float), typeof(bool) }, 1f, false);
            Call(road, "Refresh", Type.EmptyTypes);
            float actualWidth = (float)Call(modularRoad, "GetRoadWidth", Type.EmptyTypes);
            if (Mathf.Abs(actualWidth - width) > .1f)
                throw new InvalidOperationException(name + ": EasyRoads width differs from the lane envelope.");
            if (!modularRoad.GetComponentsInChildren<MeshCollider>(true).Any(IsRoadCollider))
                throw new InvalidOperationException(name + ": EasyRoads produced no enabled mesh collision.");
            EditorUtility.SetDirty(modularRoad);
            return modularRoad;
        }

        internal MeshCollider[] Colliders => instance.GetComponentsInChildren<MeshCollider>(true)
            .Where(IsRoadCollider).ToArray();

        internal void PersistMeshes(string folder)
        {
            var meshes = instance.GetComponentsInChildren<MeshFilter>(true).Select(f => f.sharedMesh)
                .Concat(instance.GetComponentsInChildren<MeshCollider>(true).Select(c => c.sharedMesh))
                .Where(m => m != null && !AssetDatabase.Contains(m)).Distinct().ToArray();
            var replacements = new Dictionary<Mesh, Mesh>();
            for (int i = 0; i < meshes.Length; i++)
            {
                string path = folder + "/EasyRoadsMesh_" + i.ToString("D3") + ".asset";
                Mesh persistent = AssetDatabase.LoadAssetAtPath<Mesh>(path);
                if (persistent == null)
                {
                    persistent = UnityEngine.Object.Instantiate(meshes[i]);
                    AssetDatabase.CreateAsset(persistent, path);
                }
                else EditorUtility.CopySerialized(meshes[i], persistent);
                EditorUtility.SetDirty(persistent);
                replacements.Add(meshes[i], persistent);
            }
            // Preserve every serialized vendor instance reference to these exact vendor-generated meshes.
            foreach (Component component in instance.GetComponentsInChildren<Component>(true))
            {
                if (component == null) continue;
                var serialized = new SerializedObject(component);
                SerializedProperty property = serialized.GetIterator();
                while (property.Next(true))
                    if (property.propertyType == SerializedPropertyType.ObjectReference &&
                        property.objectReferenceValue is Mesh mesh &&
                        replacements.TryGetValue(mesh, out Mesh persistent))
                        property.objectReferenceValue = persistent;
                serialized.ApplyModifiedPropertiesWithoutUndo();
            }
        }

        private static bool IsRoadCollider(MeshCollider collider) =>
            collider.enabled && !collider.isTrigger && collider.gameObject.activeInHierarchy &&
            collider.sharedMesh != null && collider.sharedMesh.vertexCount > 2;

        private static Type RequireType(string shortName)
        {
            string name = "EasyRoads3Dv3." + shortName;
            return AppDomain.CurrentDomain.GetAssemblies().Select(a => a.GetType(name, false))
                .FirstOrDefault(t => t != null) ?? throw new TypeLoadException(name + " is unavailable.");
        }

        private static object Call(object target, string method, Type[] signature, params object[] arguments)
        {
            MethodInfo api = target.GetType().GetMethod(method, BindingFlags.Public | BindingFlags.Instance,
                null, signature, null) ?? throw new MissingMethodException(target.GetType().FullName, method);
            try { return api.Invoke(target, arguments); }
            catch (TargetInvocationException ex)
            { throw new InvalidOperationException("EasyRoads " + method + " failed.", ex.InnerException ?? ex); }
        }

        private static void Set(object target, string field, object value)
        {
            FieldInfo api = target.GetType().GetField(field, BindingFlags.Public | BindingFlags.Instance)
                ?? throw new MissingFieldException(target.GetType().FullName, field);
            api.SetValue(target, value);
        }
    }
}
